import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> {'side','price','qty','seq'}
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def clean_buy_top():
        while buy_heap:
            price, seq, oid = buy_heap[0]
            price = -price
            if oid not in book or book[oid]['qty'] <= 0 or book[oid]['side'] != 'buy':
                heapq.heappop(buy_heap)
            else:
                return True
        return False

    def clean_sell_top():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            if oid not in book or book[oid]['qty'] <= 0 or book[oid]['side'] != 'sell':
                heapq.heappop(sell_heap)
            else:
                return True
        return False

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['qty'] = 0
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0 and clean_sell_top():
                s_price, s_seq, s_id = sell_heap[0]
                if price is not None and s_price > price:
                    break
                resting = book[s_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, s_id, s_price, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    if s_id in book:
                        del book[s_id]
            if typ == 'limit' and remaining > 0:
                seq = next_seq()
                book[oid] = {'side':'buy','price':price,'qty':remaining,'seq':seq}
                heapq.heappush(buy_heap, (-price, seq, oid))
        else:  # sell
            while remaining > 0 and clean_buy_top():
                b_price_neg, b_seq, b_id = buy_heap[0]
                b_price = -b_price_neg
                if price is not None and b_price < price:
                    break
                resting = book[b_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([b_id, oid, b_price, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    if b_id in book:
                        del book[b_id]
            if typ == 'limit' and remaining > 0:
                seq = next_seq()
                book[oid] = {'side':'sell','price':price,'qty':remaining,'seq':seq}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

